library;

import 'dart:async';
import 'dart:isolate';

import 'package:flutter_test/flutter_test.dart';
import 'package:posthog_flutter/posthog_flutter.dart';
import 'package:posthog_flutter/src/posthog_flutter_platform_interface.dart';

import 'posthog_flutter_platform_interface_fake.dart';

void main() {
  test('repeated setup turns the isolate hook off and back on', () async {
    final results = ReceivePort();
    final isolate = await Isolate.spawn(
      _exerciseIsolateHook,
      results.sendPort,
      errorsAreFatal: false,
      onExit: results.sendPort,
    );
    addTearDown(() {
      isolate.kill(priority: Isolate.immediate);
      results.close();
    });

    expect(await results.first, [1, 0, 1]);
  });
}

Future<void> _exerciseIsolateHook(SendPort results) async {
  final observedErrors = ReceivePort();
  final errors = StreamIterator<dynamic>(observedErrors);
  Isolate.current.addErrorListener(observedErrors.sendPort);
  final platform = PosthogFlutterPlatformFake();
  PosthogFlutterPlatformInterface.instance = platform;

  try {
    final counts = <int>[];
    for (final enabled in [true, false, true]) {
      await Posthog().setup(PostHogConfig('test-token')
        ..errorTrackingConfig.captureIsolateErrors = enabled);
      platform.capturedExceptions.clear();
      Timer.run(() => throw StateError('isolate hook enabled=$enabled'));
      await errors.moveNext();
      // Error listeners use separate ports; let the SDK's queued callback run.
      await Future<void>.delayed(Duration.zero);
      counts.add(platform.capturedExceptions.length);
    }
    results.send(counts);
  } catch (error, stack) {
    results.send('$error\n$stack');
  } finally {
    await Posthog().close();
    Isolate.current.removeErrorListener(observedErrors.sendPort);
    await errors.cancel();
    observedErrors.close();
  }
}

import 'dart:ui';

import 'package:flutter/foundation.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:posthog_flutter/posthog_flutter.dart';
import 'package:posthog_flutter/src/posthog_flutter_platform_interface.dart';

import 'posthog_flutter_platform_interface_fake.dart';

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  late PosthogFlutterPlatformFake platform;
  FlutterExceptionHandler? originalFlutterHandler;
  ErrorCallback? originalPlatformHandler;

  setUp(() async {
    platform = PosthogFlutterPlatformFake();
    PosthogFlutterPlatformInterface.instance = platform;
    await Posthog().close();
    originalFlutterHandler = FlutterError.onError;
    FlutterError.onError = (_) {};
    if (!kIsWeb) {
      originalPlatformHandler = PlatformDispatcher.instance.onError;
      PlatformDispatcher.instance.onError = (_, __) => true;
    }
  });

  tearDown(() async {
    await Posthog().close();
    FlutterError.onError = originalFlutterHandler;
    if (!kIsWeb) {
      PlatformDispatcher.instance.onError = originalPlatformHandler;
    }
  });

  void reportFlutterError({bool silent = false}) {
    FlutterError.reportError(FlutterErrorDetails(
      exception: StateError('repeated setup repro'),
      stack: StackTrace.current,
      silent: silent,
    ));
  }

  for (final reuseConfig in [false, true]) {
    test('disables Flutter hook on repeated setup (reuse=$reuseConfig)',
        () async {
      final upstream = FlutterError.onError;
      final first = PostHogConfig('test-token')
        ..errorTrackingConfig.captureFlutterErrors = true;
      await Posthog().setup(first);
      reportFlutterError();
      expect(platform.capturedExceptions, hasLength(1));
      platform.capturedExceptions.clear();

      final second = reuseConfig ? first : PostHogConfig('test-token');
      second.errorTrackingConfig.captureFlutterErrors = false;
      await Posthog().setup(second);
      expect(Posthog().config, same(second));

      reportFlutterError();
      expect(platform.capturedExceptions, isEmpty);
      expect(FlutterError.onError, same(upstream));
    });
  }

  test('disables PlatformDispatcher hook on repeated setup', () async {
    final upstream = PlatformDispatcher.instance.onError;
    final first = PostHogConfig('test-token')
      ..errorTrackingConfig.capturePlatformDispatcherErrors = true;
    await Posthog().setup(first);
    PlatformDispatcher.instance.onError!(
        StateError('before'), StackTrace.current);
    expect(platform.capturedExceptions, hasLength(1));
    platform.capturedExceptions.clear();

    await Posthog().setup(PostHogConfig('test-token'));
    PlatformDispatcher.instance.onError!(
        StateError('after'), StackTrace.current);
    expect(platform.capturedExceptions, isEmpty);
    expect(PlatformDispatcher.instance.onError, same(upstream));
  }, skip: kIsWeb);

  test('adds PlatformDispatcher hook while Flutter hook is installed',
      () async {
    final first = PostHogConfig('test-token')
      ..errorTrackingConfig.captureFlutterErrors = true;
    await Posthog().setup(first);

    final second = PostHogConfig('test-token')
      ..errorTrackingConfig.captureFlutterErrors = true
      ..errorTrackingConfig.capturePlatformDispatcherErrors = true;
    await Posthog().setup(second);
    expect(Posthog().config, same(second));

    PlatformDispatcher.instance.onError!(
        StateError('after'), StackTrace.current);
    expect(platform.capturedExceptions, hasLength(1));
  }, skip: kIsWeb);

  test('replaces silent-error policy on repeated setup', () async {
    final first = PostHogConfig('test-token')
      ..errorTrackingConfig.captureFlutterErrors = true;
    await Posthog().setup(first);

    final second = PostHogConfig('test-token')
      ..errorTrackingConfig.captureFlutterErrors = true
      ..errorTrackingConfig.captureSilentFlutterErrors = true;
    await Posthog().setup(second);

    reportFlutterError(silent: true);
    expect(platform.capturedExceptions, hasLength(1));
  });

  test('mutating the original silent-error policy takes effect', () async {
    final config = PostHogConfig('test-token')
      ..errorTrackingConfig.captureFlutterErrors = true;
    await Posthog().setup(config);
    config.errorTrackingConfig.captureSilentFlutterErrors = true;
    await Posthog().setup(config);

    reportFlutterError(silent: true);
    expect(platform.capturedExceptions, hasLength(1));
  });

  test('first installation can happen on second setup', () async {
    await Posthog().setup(PostHogConfig('test-token'));
    await Posthog().setup(PostHogConfig('test-token')
      ..errorTrackingConfig.captureFlutterErrors = true);

    reportFlutterError();
    expect(platform.capturedExceptions, hasLength(1));
  });

  test('identical repeated setup does not duplicate capture', () async {
    final config = PostHogConfig('test-token')
      ..errorTrackingConfig.captureFlutterErrors = true;
    await Posthog().setup(config);
    await Posthog().setup(config);

    reportFlutterError();
    expect(platform.capturedExceptions, hasLength(1));
  });

  for (final platformHandler in [false, true]) {
    test(
        'repeated setup preserves wrapped handlers (platform=$platformHandler)',
        () async {
      var upstreamCalls = 0;
      var wrapperCalls = 0;
      final config = PostHogConfig('test-token')
        ..errorTrackingConfig.captureFlutterErrors = !platformHandler
        ..errorTrackingConfig.capturePlatformDispatcherErrors = platformHandler;

      if (platformHandler) {
        PlatformDispatcher.instance.onError = (_, __) {
          upstreamCalls++;
          return true;
        };
      } else {
        FlutterError.onError = (_) => upstreamCalls++;
      }
      await Posthog().setup(config);
      if (platformHandler) {
        final delegate = PlatformDispatcher.instance.onError!;
        PlatformDispatcher.instance.onError = (error, stack) {
          wrapperCalls++;
          return delegate(error, stack);
        };
      } else {
        final delegate = FlutterError.onError!;
        FlutterError.onError = (details) {
          wrapperCalls++;
          delegate(details);
        };
      }

      for (var i = 0; i < 3; i++) {
        await Posthog().setup(config);
      }
      if (platformHandler) {
        expect(
          PlatformDispatcher.instance.onError!(
              StateError('after'), StackTrace.current),
          isTrue,
        );
      } else {
        reportFlutterError();
      }
      expect(platform.capturedExceptions, hasLength(1));
      expect(upstreamCalls, 1);
      expect(wrapperCalls, 1);
    }, skip: kIsWeb && platformHandler);
  }

  test('close then setup applies changed hook flags', () async {
    await Posthog().setup(PostHogConfig('test-token')
      ..errorTrackingConfig.captureFlutterErrors = true);
    await Posthog().close();
    await Posthog().setup(PostHogConfig('test-token')
      ..errorTrackingConfig.capturePlatformDispatcherErrors = true);

    reportFlutterError();
    expect(platform.capturedExceptions, isEmpty);
    PlatformDispatcher.instance.onError!(
        StateError('after'), StackTrace.current);
    expect(platform.capturedExceptions, hasLength(1));
  }, skip: kIsWeb);
}

import 'dart:async';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:posthog_flutter/src/core/file_storage.dart';
import 'package:posthog_flutter/src/core/persistence.dart';
import 'package:posthog_flutter/src/posthog_config.dart';
import 'package:posthog_flutter/src/posthog_desktop_client.dart';

import '../posthog_api_fake.dart';
import 'test_client.dart';

void main() {
  late LocalPostHogServer server;
  late Directory dir;

  setUp(() async {
    server = await LocalPostHogServer.start();
    dir = tempDirectory();
  });

  /// A launch of the app with [bootstrap]: its client, and the storage the
  /// client keeps its state in.
  (DesktopPostHog, FileStorage) launch([PostHogBootstrapConfig? bootstrap]) {
    final storage = FileStorage(dir.path);
    final client = testClient(server,
        config: testConfig(bootstrap: bootstrap), storage: storage);
    return (client, storage);
  }

  group('Bootstrapped identity', () {
    test('seeds the anonymous id on a fresh install', () {
      final (client, storage) =
          launch(const PostHogBootstrapConfig(distinctId: 'anon-abc'));

      expect(client.getDistinctId(), 'anon-abc');
      expect(_isIdentified(storage), isFalse);
      client.identify('user-1');
      expect(queuedPropsOf(storage, r'$identify')[r'$anon_distinct_id'],
          'anon-abc');
    });

    test('seeds an identified user, but not as the device id', () async {
      final (client, storage) = launch(const PostHogBootstrapConfig(
          distinctId: 'user-123', isIdentifiedId: true));

      await client.reloadFeatureFlagsAsync();

      expect(client.getDistinctId(), 'user-123');
      expect(_isIdentified(storage), isTrue);
      expect(server.flagsRequests.last.body[r'$device_id'], isNot('user-123'),
          reason: 'device-level bucketing must never use the person id');
      expect(getQueue(storage), isEmpty,
          reason: 'a fresh install has no anonymous history to link');
    });

    test('never replaces a stored anonymous id', () {
      final (earlier, _) = launch();
      final anonymousId = earlier.getDistinctId();
      earlier.close();

      final (client, _) =
          launch(const PostHogBootstrapConfig(distinctId: 'anon-new'));

      expect(client.getDistinctId(), anonymousId);
    });

    test('an identified bootstrap merges a stored anonymous user', () {
      final (earlier, _) = launch();
      final anonymousId = earlier.getDistinctId();
      earlier.close();

      final (client, storage) = launch(const PostHogBootstrapConfig(
          distinctId: 'user-123', isIdentifiedId: true));

      expect(client.getDistinctId(), 'user-123');
      final identify = queuedPropsOf(storage, r'$identify');
      expect(identify[r'$anon_distinct_id'], anonymousId);
    });

    test('an identified bootstrap keeps a different identified user', () {
      final (earlier, _) = launch();
      earlier
        ..identify('user-existing')
        ..close();

      final (client, storage) = launch(const PostHogBootstrapConfig(
          distinctId: 'user-123', isIdentifiedId: true));

      expect(client.getDistinctId(), 'user-existing');
      expect(queuedEvents(storage), [r'$identify']);
    });

    test('an identified bootstrap of the stored anonymous id sends nothing',
        () {
      final (earlier, _) = launch();
      final anonymousId = earlier.getDistinctId();
      earlier.close();

      final (client, storage) = launch(PostHogBootstrapConfig(
          distinctId: anonymousId, isIdentifiedId: true));

      expect(client.getDistinctId(), anonymousId);
      expect(_isIdentified(storage), isTrue);
      expect(getQueue(storage), isEmpty);
    });

    test('an identified bootstrap is reconciled while opted out, silently', () {
      final (earlier, _) = launch();
      earlier
        ..getDistinctId()
        ..optOut()
        ..close();

      final (client, storage) = launch(const PostHogBootstrapConfig(
          distinctId: 'user-123', isIdentifiedId: true));

      expect(client.getDistinctId(), 'user-123');
      expect(_isIdentified(storage), isTrue,
          reason: 'opting out stops events, not the local identity');
      expect(getQueue(storage), isEmpty);
    });
  });

  group('Bootstrapped feature flags', () {
    test('are served before the first flags response', () {
      final (client, _) = launch(const PostHogBootstrapConfig(featureFlags: {
        'beta-ui': true,
        'checkout': 'variant-a',
      }, featureFlagPayloads: {
        'checkout': {'color': 'blue'},
      }));

      expect(client.getFeatureFlag('beta-ui'), isTrue);
      expect(client.getFeatureFlag('checkout'), 'variant-a');
      expect(client.getFeatureFlagResult('checkout', sendEvent: false)?.payload,
          {'color': 'blue'});
    });

    test('are not served when disabled, nor are their payloads', () {
      final (client, _) = launch(const PostHogBootstrapConfig(
          featureFlags: {'enabled': true, 'disabled': false, 'empty': ''},
          featureFlagPayloads: {'disabled': 'hidden'}));

      expect(client.getFeatureFlag('enabled'), isTrue);
      expect(client.getFeatureFlag('disabled'), isNull);
      expect(client.getFeatureFlag('empty'), isNull);
      expect(client.getFeatureFlagResult('disabled', sendEvent: false)?.payload,
          isNull);
    });

    test('replace flags stored by an earlier session', () async {
      server.respond = (_) => _flagsResponse({
            'checkout': _flag('checkout', enabled: false),
            'other': _flag('other'),
          });
      final (earlier, _) = launch();
      await earlier.reloadFeatureFlagsAsync();
      earlier.close();

      final (client, _) = launch(
          const PostHogBootstrapConfig(featureFlags: {'checkout': true}));

      expect(client.getFeatureFlag('checkout'), isTrue);
      expect(client.getFeatureFlag('other'), isNull);
    });

    test('a supplied disabled-only snapshot clears stored flags', () async {
      server.respond = (_) =>
          _flagsResponse({'stale': _flag('stale', payload: '{"secret":true}')});
      final (earlier, _) = launch();
      await earlier.reloadFeatureFlagsAsync();
      expect(
        earlier.getFeatureFlagResult('stale', sendEvent: false)?.payload,
        {'secret': true},
      );
      earlier.close();

      final (client, storage) = launch(const PostHogBootstrapConfig(
        featureFlags: {'disabled': false, 'empty': ''},
        featureFlagPayloads: {'disabled': 'hidden'},
      ));
      final announced = Completer<void>();
      client.onFeatureFlags(announced.complete);

      await announced.future;

      expect(client.getFeatureFlag('stale'), isNull);
      expect(client.getFeatureFlag('disabled'), isNull);
      expect(
        client.getFeatureFlagResult('stale', sendEvent: false)?.payload,
        isNull,
      );
      expect(
        storage.getProperty<Map<String, Object?>>(
          PostHogPersistedProperty.featureFlagDetails,
        ),
        {'flags': <String, Object?>{}},
      );
    });

    for (final (description, bootstrap) in [
      ('absent', const PostHogBootstrapConfig()),
      ('empty', const PostHogBootstrapConfig(featureFlags: {})),
    ]) {
      test('an $description snapshot leaves stored flags unchanged', () async {
        server.respond = (_) => _flagsResponse({'stored': _flag('stored')});
        final (earlier, _) = launch();
        await earlier.reloadFeatureFlagsAsync();
        earlier.close();

        final (client, _) = launch(bootstrap);

        expect(client.getFeatureFlag('stored'), isTrue);
      });
    }

    test('are replaced by a complete flags response', () async {
      final (client, _) = launch(const PostHogBootstrapConfig(featureFlags: {
        'beta-ui': 'variant-a',
        'legacy': true
      }, featureFlagPayloads: {
        'beta-ui': {'color': 'blue'},
      }));
      server.respond = (_) =>
          _flagsResponse({'beta-ui': _flag('beta-ui', variant: 'variant-b')});

      await client.reloadFeatureFlagsAsync();

      expect(client.getFeatureFlag('beta-ui'), 'variant-b');
      expect(client.getFeatureFlagResult('beta-ui', sendEvent: false)?.payload,
          isNull);
      expect(client.getFeatureFlag('legacy'), isNull);
    });

    test('keep what an errored flags response did not compute', () async {
      final (client, _) = launch(const PostHogBootstrapConfig(
          featureFlags: {'beta-ui': true, 'legacy': true}));
      server.respond = (_) => _flagsResponse(
          {'beta-ui': _flag('beta-ui', enabled: false)},
          errorsWhileComputingFlags: true);

      await client.reloadFeatureFlagsAsync();

      expect(client.getFeatureFlag('beta-ui'), isFalse);
      expect(client.getFeatureFlag('legacy'), isTrue);
    });

    test('are dropped by reset', () async {
      final (client, _) =
          launch(const PostHogBootstrapConfig(featureFlags: {'legacy': true}));
      server.respond = (_) => _flagsResponse({});

      client.reset();
      await client.reloadFeatureFlagsAsync();

      expect(client.getFeatureFlag('legacy'), isNull);
    });

    test('notify flags listeners right after setup', () async {
      final (client, _) =
          launch(const PostHogBootstrapConfig(featureFlags: {'beta-ui': true}));
      final loaded = Completer<void>();
      client.onFeatureFlags(loaded.complete);

      await loaded.future;

      expect(client.getFeatureFlag('beta-ui'), isTrue);
      await client.reloadFeatureFlagsAsync();
      expect(server.flagsRequests, hasLength(1),
          reason: 'the bootstrapped flags need no request of their own');
    });

    test(r'are reported on $feature_flag_called until flags load', () async {
      final (client, storage) =
          launch(const PostHogBootstrapConfig(featureFlags: {
        'beta-ui': 'variant-a',
      }, featureFlagPayloads: {
        'beta-ui': {'color': 'blue'},
      }));

      client.getFeatureFlag('beta-ui');
      server.respond = (_) =>
          _flagsResponse({'beta-ui': _flag('beta-ui', variant: 'variant-b')});
      await client.reloadFeatureFlagsAsync();
      client.getFeatureFlag('beta-ui');

      final calls = [
        for (final message in getQueue(storage))
          if (message['event'] == r'$feature_flag_called')
            message['properties']! as Map<String, Object?>,
      ];
      expect(calls, hasLength(2));
      expect(calls[0][r'$feature_flag_response'], 'variant-a');
      expect(calls[0][r'$feature_flag_bootstrapped_response'], 'variant-a');
      expect(
          calls[0][r'$feature_flag_bootstrapped_payload'], {'color': 'blue'});
      expect(calls[0][r'$used_bootstrap_value'], isTrue);
      expect(calls[1][r'$feature_flag_response'], 'variant-b');
      expect(calls[1][r'$used_bootstrap_value'], isFalse);
    });

    test(r'are reported unused after a quota-limited flags response', () async {
      final (client, storage) =
          launch(const PostHogBootstrapConfig(featureFlags: {'beta-ui': true}));
      server.respond =
          (_) => _flagsResponse({}, quotaLimited: ['feature_flags']);
      await client.reloadFeatureFlagsAsync();

      expect(client.getFeatureFlag('beta-ui'), isTrue,
          reason: 'cached flags keep serving under the quota limit');

      final props = queuedPropsOf(storage, r'$feature_flag_called');
      expect(props[r'$feature_flag_bootstrapped_response'], isTrue);
      expect(props[r'$used_bootstrap_value'], isFalse,
          reason: 'PostHog answered the /flags request');
    });

    test(r'are not reported for flags that were not bootstrapped', () async {
      final (client, storage) =
          launch(const PostHogBootstrapConfig(featureFlags: {'beta-ui': true}));
      server.respond = (_) => _flagsResponse({'other': _flag('other')});
      await client.reloadFeatureFlagsAsync();

      client.getFeatureFlag('other');

      final props = queuedPropsOf(storage, r'$feature_flag_called');
      expect(props.containsKey(r'$used_bootstrap_value'), isFalse);
      expect(
          props.containsKey(r'$feature_flag_bootstrapped_response'), isFalse);
    });
  });
}

bool _isIdentified(FileStorage storage) =>
    storage.getProperty<String>(PostHogPersistedProperty.personMode) ==
    'identified';

Map<String, Object?> _flag(
  String key, {
  bool enabled = true,
  String? variant,
  String? payload,
}) =>
    {
      'key': key,
      'enabled': enabled,
      if (variant != null) 'variant': variant,
      if (payload != null)
        'metadata': {
          'payload': payload,
        },
    };

PostHogResponse _flagsResponse(
  Map<String, Object?> flags, {
  bool errorsWhileComputingFlags = false,
  List<String>? quotaLimited,
}) =>
    PostHogResponse.json({
      'flags': flags,
      'errorsWhileComputingFlags': errorsWhileComputingFlags,
      if (quotaLimited != null) 'quotaLimited': quotaLimited,
    });

