import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:posthog_flutter_sdk_compliance_adapter/adapter_server.dart';

void main() {
  test(
    'capture converts a non-UTC override to the equivalent UTC instant',
    () async {
      expect(
        (await _captureTimestamp('2024-03-01T12:30:00-05:00')).timestamp,
        '2024-03-01T17:30:00.000Z',
      );
    },
  );

  test('capture replaces an invalid timestamp with the current UTC time',
      () async {
    final capture = await _captureTimestamp('invalid');
    final timestamp = DateTime.parse(capture.timestamp);

    expect(timestamp.isUtc, isTrue);
    expect(timestamp.isBefore(capture.before), isFalse);
    expect(timestamp.isAfter(capture.after), isFalse);
  });
}

Future<({String timestamp, DateTime before, DateTime after})> _captureTimestamp(
    String timestamp) async {
  final uploadedBody = Completer<Map<String, Object?>>();
  final ingestion = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
  addTearDown(() => ingestion.close(force: true));
  unawaited(() async {
    await for (final request in ingestion) {
      final body = jsonDecode(await utf8.decoder.bind(request).join())
          as Map<String, Object?>;
      if (!uploadedBody.isCompleted) uploadedBody.complete(body);
      request.response.statusCode = HttpStatus.ok;
      await request.response.close();
    }
  }());

  final adapter = ComplianceAdapter();
  final adapterServer = await adapter.start(port: 0);
  addTearDown(adapter.close);

  final client = HttpClient();
  addTearDown(client.close);
  final port = adapterServer.port;
  await _post(client, port, '/init', {
    'api_key': 'phc_test',
    'host': 'http://127.0.0.1:${ingestion.port}',
    'flush_at': 100,
    'flush_interval_ms': 60000,
  });
  final before = DateTime.now().toUtc();
  await _post(client, port, '/capture', {
    'distinct_id': 'user-1',
    'event': 'order completed',
    'timestamp': timestamp,
  });
  final after = DateTime.now().toUtc();
  await _post(client, port, '/flush', {});

  final body = await uploadedBody.future;
  final batch = body['batch'] as List<Object?>;
  final event = batch.single! as Map<String, Object?>;
  return (
    timestamp: event['timestamp']! as String,
    before: before,
    after: after
  );
}

Future<Map<String, Object?>> _post(
  HttpClient client,
  int port,
  String path,
  Map<String, Object?> body,
) async {
  final request = await client.post('127.0.0.1', port, path);
  request.headers.contentType = ContentType.json;
  request.write(jsonEncode(body));
  final response = await request.close();
  return jsonDecode(await response.transform(utf8.decoder).join())
      as Map<String, Object?>;
}

import 'package:flutter_test/flutter_test.dart';

import '../../scripts/annotate-api-dart.dart';

void main() {
  Map<String, dynamic> snapshot() => {
        'packageApi': {
          'interfaceDeclarations': [
            {
              'name': 'Config',
              'relativePath': 'lib/config.dart',
              'fieldDeclarations': [
                for (final name in [
                  'getterOnly',
                  'setterOnly',
                  'paired',
                  'stable',
                  'deprecatedGetter',
                  'deprecatedSetter',
                ])
                  {
                    'name': name,
                    'isExperimental': false,
                    'isDeprecated': false
                  },
                {
                  'name': 'plainField',
                  'isExperimental': true,
                  'isDeprecated': false
                },
              ],
            },
            {
              'name': 'OtherConfig',
              'relativePath': 'lib/config.dart',
              'fieldDeclarations': [
                {
                  'name': 'paired',
                  'isExperimental': false,
                  'isDeprecated': false
                },
              ],
            },
          ],
        },
      };

  const source = '''
import 'package:meta/meta.dart';

class Config {
  @experimental
  int get getterOnly => 1;

  @experimental
  set setterOnly(int value) {}

  int get paired => 1;
  @experimental
  set paired(int value) {}

  // @experimental is not an annotation on this property.
  int get stable => 1;
  set stable(int value) {}

  @experimental
  int plainField = 1;

  @Deprecated('Use paired instead.')
  int get deprecatedGetter => 1;
  @Deprecated('Use paired instead.')
  set deprecatedGetter(int value) {}

  int get deprecatedSetter => 1;
  @deprecated
  set deprecatedSetter(int value) {}
}

class OtherConfig {
  int get paired => 1;
  set paired(int value) {}
}
''';

  test('accessor annotations are recorded on their properties', () {
    final api = snapshot();
    final reads = <String>[];
    annotateAccessors(api, (path) {
      reads.add(path);
      return source;
    });

    final packageApi = api['packageApi'] as Map<String, dynamic>;
    final interfaces = (packageApi['interfaceDeclarations'] as List)
        .cast<Map<String, dynamic>>();
    final fields = (interfaces.first['fieldDeclarations'] as List)
        .cast<Map<String, dynamic>>();
    expect(
      {
        for (final field in fields)
          field['name']: (field['isExperimental'], field['isDeprecated'])
      },
      {
        'getterOnly': (true, false),
        'setterOnly': (true, false),
        'paired': (true, false),
        'stable': (false, false),
        'deprecatedGetter': (false, true),
        'deprecatedSetter': (false, true),
        'plainField': (true, false),
      },
    );
    expect(interfaces.last['fieldDeclarations'], [
      {'name': 'paired', 'isExperimental': false, 'isDeprecated': false},
    ]);
    expect(reads, ['lib/config.dart']);
  });

  test('removing accessor annotations leaves regenerated properties stable',
      () {
    final api = snapshot();
    annotateAccessors(
      api,
      (_) => source
          .replaceAll('@experimental', '')
          .replaceAll(RegExp(r"@Deprecated\('[^']*'\)"), '')
          .replaceAll('@deprecated', ''),
    );

    final packageApi = api['packageApi'] as Map<String, dynamic>;
    final interfaces = (packageApi['interfaceDeclarations'] as List)
        .cast<Map<String, dynamic>>();
    final fields = (interfaces.first['fieldDeclarations'] as List)
        .cast<Map<String, dynamic>>();
    expect(
      fields.where((field) => field['name'] != 'plainField').every((field) =>
          field['isExperimental'] == false && field['isDeprecated'] == false),
      isTrue,
    );
  });
}

import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:posthog_flutter_sdk_compliance_adapter/adapter_server.dart';

void main() {
  test(
    r'gated flag without experiment sends exactly the minimal allowlist',
    () async {
      final mockServer = await _MockPostHogServer.start({
        'flags': {
          'plain-flag': {
            'key': 'plain-flag',
            'enabled': true,
            'metadata': {'has_experiment': false},
          },
        },
        'featureFlags': {'plain-flag': true},
        'minimalFlagCalledEvents': true,
      });
      addTearDown(mockServer.close);

      final harness = await _AdapterHarness.start(mockServer);
      addTearDown(harness.close);

      final properties = await harness.captureFeatureFlagCalled('plain-flag');

      expect(
        properties.keys,
        unorderedEquals([
          'distinct_id',
          'token',
          r'$lib',
          r'$lib_version',
          r'$feature_flag',
          r'$feature_flag_response',
          r'$feature_flag_has_experiment',
        ]),
      );
      expect(properties['distinct_id'], 'test-user');
      expect(properties['token'], 'test-api-key');
      expect(properties[r'$feature_flag'], 'plain-flag');
      expect(properties[r'$feature_flag_response'], isTrue);
      expect(properties[r'$feature_flag_has_experiment'], isFalse);
    },
  );

  final fullEventCases = [
    (
      description: 'gated flag with an experiment sends the full event',
      response: <String, Object?>{
        'flags': {
          'experiment-flag': {
            'key': 'experiment-flag',
            'enabled': true,
            'variant': 'control',
            'metadata': {'has_experiment': true},
          },
        },
        'featureFlags': {'experiment-flag': 'control'},
        'minimalFlagCalledEvents': true,
      },
      key: 'experiment-flag',
      expectedHasExperiment: isTrue,
    ),
    (
      description: 'ungated flag without experiment sends the full event',
      response: <String, Object?>{
        'flags': {
          'plain-flag': {
            'key': 'plain-flag',
            'enabled': true,
            'metadata': {'has_experiment': false},
          },
        },
        'featureFlags': {'plain-flag': true},
      },
      key: 'plain-flag',
      expectedHasExperiment: isFalse,
    ),
    (
      description: 'gated flag with unreported has_experiment sends the '
          'full event',
      response: <String, Object?>{
        'featureFlags': {'plain-flag': true},
        'minimalFlagCalledEvents': true,
      },
      key: 'plain-flag',
      expectedHasExperiment: isNull,
    ),
    (
      description: 'gated flag with malformed has_experiment metadata sends '
          'the full event',
      response: <String, Object?>{
        'flags': {
          'plain-flag': {
            'key': 'plain-flag',
            'enabled': true,
            'metadata': {'has_experiment': 'not-a-bool'},
          },
        },
        'featureFlags': {'plain-flag': true},
        'minimalFlagCalledEvents': true,
      },
      key: 'plain-flag',
      expectedHasExperiment: isNull,
    ),
  ];

  for (final testCase in fullEventCases) {
    test(testCase.description, () async {
      final mockServer = await _MockPostHogServer.start(testCase.response);
      addTearDown(mockServer.close);

      final harness = await _AdapterHarness.start(mockServer);
      addTearDown(harness.close);

      final properties = await harness.captureFeatureFlagCalled(testCase.key);

      expect(properties[r'$feature_flag'], testCase.key);
      expect(properties, contains(r'$feature/' + testCase.key));
      expect(
        properties[r'$feature_flag_has_experiment'],
        testCase.expectedHasExperiment,
      );
    });
  }

  test('the gate tracks the latest flags response', () async {
    final mockServer = await _MockPostHogServer.start({
      'flags': {
        'plain-flag': {
          'key': 'plain-flag',
          'enabled': true,
          'metadata': {'has_experiment': false},
        },
      },
      'featureFlags': {'plain-flag': true},
      'minimalFlagCalledEvents': true,
    });
    addTearDown(mockServer.close);

    final harness = await _AdapterHarness.start(mockServer);
    addTearDown(harness.close);

    final gated = await harness.captureFeatureFlagCalled('plain-flag');
    expect(gated, isNot(contains(r'$feature/plain-flag')));

    mockServer.flagsResponse = Map.of(mockServer.flagsResponse)
      ..remove('minimalFlagCalledEvents');

    final ungated = await harness.captureFeatureFlagCalled('plain-flag');
    expect(ungated, contains(r'$feature/plain-flag'));
  });
}

/// Runs a [ComplianceAdapter] against a [_MockPostHogServer].
class _AdapterHarness {
  _AdapterHarness._(this._adapter, this._baseUrl, this._mockServer);

  final ComplianceAdapter _adapter;
  final String _baseUrl;
  final _MockPostHogServer _mockServer;

  static Future<_AdapterHarness> start(_MockPostHogServer mockServer) async {
    final adapter = ComplianceAdapter();
    final adapterServer = await adapter.start(port: 0);
    final baseUrl = 'http://127.0.0.1:${adapterServer.port}';
    await _postJson('$baseUrl/init', {
      'api_key': '[REDACTED]',
      'host': mockServer.url,
      'flush_interval_ms': 60000,
    });
    return _AdapterHarness._(adapter, baseUrl, mockServer);
  }

  Future<void> close() => _adapter.close();

  /// Evaluates [key], flushes, and returns the properties of the
  /// `$feature_flag_called` event it produced.
  Future<Map<String, Object?>> captureFeatureFlagCalled(String key) async {
    final alreadyBatched = _mockServer.batchedEvents.length;
    final response = await _postJson('$_baseUrl/get_feature_flag', {
      'key': key,
      'distinct_id': 'test-user',
    });
    expect(response['success'], isTrue);

    await _postJson('$_baseUrl/flush', {});

    expect(_mockServer.batchedEvents, hasLength(alreadyBatched + 1));
    final event = _mockServer.batchedEvents.last;
    expect(event['event'], r'$feature_flag_called');
    return Map<String, Object?>.from(event['properties'] as Map);
  }
}

Future<Map<String, Object?>> _postJson(
  String url,
  Map<String, Object?> payload,
) async {
  final client = HttpClient();
  try {
    final request = await client.postUrl(Uri.parse(url));
    request.headers.contentType = ContentType.json;
    request.write(jsonEncode(payload));
    final response = await request.close();
    final body = await utf8.decoder.bind(response).join();
    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw HttpException('HTTP ${response.statusCode}: $body');
    }
    return Map<String, Object?>.from(jsonDecode(body) as Map);
  } finally {
    client.close(force: true);
  }
}

/// Serves `/flags/?v=2` with a swappable [flagsResponse] and records events
/// posted to `/batch`.
class _MockPostHogServer {
  _MockPostHogServer._(this._server, this.flagsResponse);

  final HttpServer _server;
  Map<String, Object?> flagsResponse;
  final List<Map<String, Object?>> batchedEvents = [];

  String get url => 'http://127.0.0.1:${_server.port}';

  static Future<_MockPostHogServer> start(
    Map<String, Object?> flagsResponse,
  ) async {
    final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
    final mockServer = _MockPostHogServer._(server, flagsResponse);
    unawaited(mockServer._serve());
    return mockServer;
  }

  Future<void> close() => _server.close(force: true);

  Future<void> _serve() async {
    await for (final request in _server) {
      final body = await utf8.decoder.bind(request).join();
      if (request.method == 'POST' &&
          request.uri.path == '/flags/' &&
          request.uri.queryParameters['v'] == '2') {
        request.response.headers.contentType = ContentType.json;
        request.response.write(jsonEncode(flagsResponse));
        await request.response.close();
        continue;
      }

      if (request.method == 'POST' && request.uri.path == '/batch') {
        final decoded = jsonDecode(body) as Map;
        for (final event in decoded['batch'] as List) {
          batchedEvents.add(Map<String, Object?>.from(event as Map));
        }
        request.response.headers.contentType = ContentType.json;
        request.response.write(jsonEncode({'status': 1}));
        await request.response.close();
        continue;
      }

      request.response.statusCode = HttpStatus.notFound;
      await request.response.close();
    }
  }
}

import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:posthog_flutter_sdk_compliance_adapter/adapter_server.dart';

void main() {
  for (final (enabled, variant, expected) in <(bool, String?, Object)>[
    (true, null, true),
    (false, null, false),
    (true, 'control', 'control'),
  ]) {
    test('v2-only flags return scalar value $expected', () async {
      final server = await _MockPostHogServer.start({
        'flags': {
          'v2-flag': {
            'key': 'v2-flag',
            'enabled': enabled,
            'variant': variant,
            'metadata': {'has_experiment': false},
          },
        },
      });
      addTearDown(server.close);
      final properties = await _captureFeatureFlagCalled(server,
          key: 'v2-flag', expectedValue: expected);
      expect(properties[r'$feature_flag_response'], expected);
      expect(properties[r'$feature_flag_has_experiment'], false);
    });
  }
  test(
    r'$feature_flag_called includes $feature_flag_has_experiment from v2 metadata',
    () async {
      final mockServer = await _MockPostHogServer.start({
        'flags': {
          'experiment-flag': {
            'key': 'experiment-flag',
            'enabled': true,
            'variant': 'control',
            'metadata': {'has_experiment': true},
          },
        },
        'featureFlags': {'experiment-flag': 'control'},
      });
      addTearDown(mockServer.close);

      final properties = await _captureFeatureFlagCalled(
        mockServer,
        key: 'experiment-flag',
      );

      expect(properties[r'$feature_flag'], 'experiment-flag');
      expect(properties[r'$feature_flag_response'], 'control');
      expect(properties[r'$feature_flag_has_experiment'], isTrue);
    },
  );

  test(
    r'$feature_flag_has_experiment is sent when the server reports false',
    () async {
      final mockServer = await _MockPostHogServer.start({
        'flags': {
          'plain-flag': {
            'key': 'plain-flag',
            'enabled': true,
            'metadata': {'has_experiment': false},
          },
        },
        'featureFlags': {'plain-flag': true},
      });
      addTearDown(mockServer.close);

      final properties = await _captureFeatureFlagCalled(
        mockServer,
        key: 'plain-flag',
      );

      expect(properties[r'$feature_flag'], 'plain-flag');
      expect(properties[r'$feature_flag_response'], isTrue);
      expect(properties[r'$feature_flag_has_experiment'], isFalse);
    },
  );

  test(
    r'$feature_flag_has_experiment is omitted when the server does not '
    'report it',
    () async {
      final mockServer = await _MockPostHogServer.start({
        'featureFlags': {'plain-flag': true},
      });
      addTearDown(mockServer.close);

      final properties = await _captureFeatureFlagCalled(
        mockServer,
        key: 'plain-flag',
      );

      expect(properties[r'$feature_flag'], 'plain-flag');
      expect(properties[r'$feature_flag_response'], isTrue);
      expect(properties, isNot(contains(r'$feature_flag_has_experiment')));
    },
  );
}

/// Evaluates [key] through the adapter, flushes, and returns the properties of
/// the captured `$feature_flag_called` event.
Future<Map<String, Object?>> _captureFeatureFlagCalled(
  _MockPostHogServer mockServer, {
  required String key,
  Object? expectedValue,
}) async {
  final adapter = ComplianceAdapter();
  final adapterServer = await adapter.start(port: 0);
  addTearDown(adapter.close);

  final adapterBase = 'http://127.0.0.1:${adapterServer.port}';
  await _postJson('$adapterBase/init', {
    'api_key': '[REDACTED]',
    'host': mockServer.url,
    'flush_interval_ms': 60000,
  });

  final response = await _postJson('$adapterBase/get_feature_flag', {
    'key': key,
    'distinct_id': 'test-user',
  });
  expect(response['success'], isTrue);
  if (expectedValue != null) expect(response['value'], expectedValue);

  await _postJson('$adapterBase/flush', {});

  expect(mockServer.batchedEvents, hasLength(1));
  final event = mockServer.batchedEvents.single;
  expect(event['event'], r'$feature_flag_called');
  return Map<String, Object?>.from(event['properties'] as Map);
}

Future<Map<String, Object?>> _postJson(
  String url,
  Map<String, Object?> payload,
) async {
  final client = HttpClient();
  try {
    final request = await client.postUrl(Uri.parse(url));
    request.headers.contentType = ContentType.json;
    request.write(jsonEncode(payload));
    final response = await request.close();
    final body = await utf8.decoder.bind(response).join();
    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw HttpException('HTTP ${response.statusCode}: $body');
    }
    return Map<String, Object?>.from(jsonDecode(body) as Map);
  } finally {
    client.close(force: true);
  }
}

/// Serves `/flags/?v=2` with [flagsResponse] and records events posted to
/// `/batch`.
class _MockPostHogServer {
  _MockPostHogServer._(this._server, this._flagsResponse);

  final HttpServer _server;
  final Map<String, Object?> _flagsResponse;
  final List<Map<String, Object?>> batchedEvents = [];

  String get url => 'http://127.0.0.1:${_server.port}';

  static Future<_MockPostHogServer> start(
    Map<String, Object?> flagsResponse,
  ) async {
    final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
    final mockServer = _MockPostHogServer._(server, flagsResponse);
    unawaited(mockServer._serve());
    return mockServer;
  }

  Future<void> close() => _server.close(force: true);

  Future<void> _serve() async {
    await for (final request in _server) {
      final body = await utf8.decoder.bind(request).join();
      if (request.method == 'POST' &&
          request.uri.path == '/flags/' &&
          request.uri.queryParameters['v'] == '2') {
        request.response.headers.contentType = ContentType.json;
        request.response.write(jsonEncode(_flagsResponse));
        await request.response.close();
        continue;
      }

      if (request.method == 'POST' && request.uri.path == '/batch') {
        final decoded = jsonDecode(body) as Map;
        for (final event in decoded['batch'] as List) {
          batchedEvents.add(Map<String, Object?>.from(event as Map));
        }
        request.response.headers.contentType = ContentType.json;
        request.response.write(jsonEncode({'status': 1}));
        await request.response.close();
        continue;
      }

      request.response.statusCode = HttpStatus.notFound;
      await request.response.close();
    }
  }
}

import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

/// A request a client sent to the PostHog API.
class PostHogRequest {
  PostHogRequest._(this.path, this.headers, this.body);

  factory PostHogRequest._decode(
    String path,
    Map<String, String> headers,
    List<int> bytes,
  ) {
    if (bytes.isEmpty) return PostHogRequest._(path, headers, const {});
    final json = utf8.decode(
      headers['content-encoding'] == 'gzip' ? gzip.decode(bytes) : bytes,
    );
    return PostHogRequest._(
      path,
      headers,
      Map<String, Object?>.from(jsonDecode(json) as Map),
    );
  }

  /// The path of the endpoint, such as `/batch/` or `/flags/`.
  final String path;

  /// The headers, by lowercase name.
  final Map<String, String> headers;

  /// The JSON body, decompressed and decoded.
  final Map<String, Object?> body;

  bool get isBatch => path == '/batch/';

  bool get isFlags => path == '/flags/';

  /// The events of a `/batch/` request, oldest first.
  List<Map<String, Object?>> get events => [
        for (final event in body['batch']! as List)
          Map<String, Object?>.from(event as Map),
      ];

  /// The names of the events of a `/batch/` request, oldest first.
  List<Object?> get eventNames => [for (final event in events) event['event']];
}

/// How the PostHog API answers a request.
class PostHogResponse {
  const PostHogResponse(this.status,
      {this.body = '{"status": 1}', this.location, this.headers = const {}})
      : isDropped = false;

  /// A success with [json] as its body.
  PostHogResponse.json(Object? json)
      : this(HttpStatus.ok, body: jsonEncode(json));

  /// No answer: the connection is closed instead.
  const PostHogResponse.dropped()
      : status = 0,
        body = '',
        location = null,
        headers = const {},
        isDropped = true;

  final int status;
  final String body;

  /// Where a redirect points.
  final String? location;

  final Map<String, String> headers;

  final bool isDropped;
}

typedef PostHogResponder = FutureOr<PostHogResponse> Function(
  PostHogRequest request,
);

/// A fake of the PostHog API: records every request and answers it through
/// [respond].
abstract class PostHogApiFake {
  /// Answers the requests; a success by default. It may take its time, for
  /// a request that stays in flight.
  PostHogResponder respond = (_) => const PostHogResponse(HttpStatus.ok);

  /// The requests received, oldest first.
  final requests = <PostHogRequest>[];

  final _waiters = <({bool Function() isReady, Completer<void> done})>[];

  /// The host that reaches this API.
  String get url;

  /// Runs [create], so that the clients it creates send their requests to
  /// this API.
  T connect<T>(T Function() create);

  List<PostHogRequest> get batchRequests => [
        for (final request in requests)
          if (request.isBatch) request
      ];

  List<PostHogRequest> get flagsRequests => [
        for (final request in requests)
          if (request.isFlags) request
      ];

  /// Every event received, oldest first.
  List<Map<String, Object?>> get events =>
      [for (final request in batchRequests) ...request.events];

  List<Object?> get eventNames => [for (final event in events) event['event']];

  /// Completes with the first event named [name] once it has arrived.
  Future<Map<String, Object?>> waitForEvent(String name) async {
    await _waitUntil(() => events.any((event) => event['event'] == name));
    return events.firstWhere((event) => event['event'] == name);
  }

  /// Completes with the body of the `/flags/` request at [index] once it
  /// has arrived.
  Future<Map<String, Object?>> waitForFlagsRequest(int index) async {
    await _waitUntil(() => flagsRequests.length > index);
    return flagsRequests[index].body;
  }

  Future<PostHogResponse> _answer(PostHogRequest request) async {
    requests.add(request);
    _waiters.removeWhere((waiter) {
      if (!waiter.isReady()) return false;
      waiter.done.complete();
      return true;
    });
    return respond(request);
  }

  Future<void> _waitUntil(bool Function() isReady) {
    if (isReady()) return Future.value();
    final done = Completer<void>();
    _waiters.add((isReady: isReady, done: done));
    return done.future;
  }
}

/// The PostHog API on a local port.
class LocalPostHogServer extends PostHogApiFake {
  LocalPostHogServer._(this._server) : url = 'http://127.0.0.1:${_server.port}';

  final HttpServer _server;

  /// Where the server listens, also once it is closed.
  @override
  final String url;

  /// Starts a server, closed at the end of the test.
  static Future<LocalPostHogServer> start() async {
    final server = LocalPostHogServer._(
      await HttpServer.bind(InternetAddress.loopbackIPv4, 0),
    );
    server._server.listen(server._serve);
    addTearDown(server.close);
    return server;
  }

  @override
  T connect<T>(T Function() create) => create();

  /// The connections clients hold open to this server.
  int get openConnections => _server.connectionsInfo().total;

  /// Completes once the clients have closed every connection to this server.
  Future<void> connectionsClosed() async {
    // Real wait: the server learns about a closed socket asynchronously.
    for (var i = 0; openConnections > 0; i++) {
      if (i == 100) fail('the client kept $openConnections connection(s)');
      await Future<void>.delayed(const Duration(milliseconds: 10));
    }
  }

  Future<void> close() => _server.close(force: true);

  Future<void> _serve(HttpRequest request) async {
    try {
      final bytes = await request.fold<List<int>>(
        [],
        (all, chunk) => all..addAll(chunk),
      );
      final headers = <String, String>{};
      request.headers.forEach(
        (name, values) => headers[name] = values.join(', '),
      );
      final response = await _answer(
        PostHogRequest._decode(request.uri.path, headers, bytes),
      );
      if (response.isDropped) {
        (await request.response.detachSocket(writeHeaders: false)).destroy();
        return;
      }
      request.response.statusCode = response.status;
      response.headers.forEach(request.response.headers.set);
      final location = response.location;
      if (location != null) {
        request.response.headers.set(HttpHeaders.locationHeader, location);
      }
      request.response.write(response.body);
      await request.response.close();
    } on IOException {
      // The client went away before the answer, as closing it makes it do.
    }
  }
}

/// A PostHog API that the clients created by [connect] reach without a
/// socket. For tests that control time with fake_async, which cannot wait
/// for a socket.
class InProcessPostHogApi extends PostHogApiFake {
  /// A host that never resolves: requests do not leave the process.
  @override
  String get url => 'http://posthog.invalid';

  @override
  T connect<T>(T Function() create) => HttpOverrides.runZoned(
        create,
        createHttpClient: (_) => _InProcessHttpClient(this),
      );
}

class _InProcessHttpClient implements HttpClient {
  _InProcessHttpClient(this._api);

  final PostHogApiFake _api;

  @override
  Future<HttpClientRequest> postUrl(Uri url) async =>
      _InProcessRequest(_api, url);

  @override
  void close({bool force = false}) {}

  @override
  dynamic noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
}

class _InProcessRequest implements HttpClientRequest {
  _InProcessRequest(this._api, this.uri);

  final PostHogApiFake _api;
  final _body = <int>[];
  final _aborted = Completer<PostHogResponse>();

  @override
  final Uri uri;

  @override
  final _InProcessHeaders headers = _InProcessHeaders();

  @override
  bool followRedirects = true;

  @override
  int contentLength = -1;

  @override
  void add(List<int> data) => _body.addAll(data);

  @override
  void abort([Object? exception, StackTrace? stackTrace]) {
    if (!_aborted.isCompleted) {
      _aborted.completeError(
        exception ?? const HttpException('Request aborted'),
        stackTrace,
      );
    }
  }

  @override
  Future<HttpClientResponse> close() async {
    final response = await Future.any([
      _api._answer(PostHogRequest._decode(uri.path, headers.values, _body)),
      _aborted.future,
    ]);
    if (response.isDropped) {
      throw const HttpException(
        'Connection closed before full header was received',
      );
    }
    return _InProcessResponse(response);
  }

  @override
  dynamic noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
}

class _InProcessHeaders implements HttpHeaders {
  final values = <String, String>{};

  @override
  void set(String name, Object value, {bool preserveHeaderCase = false}) {
    values[name.toLowerCase()] = '$value';
  }

  @override
  String? value(String name) => values[name.toLowerCase()];

  @override
  dynamic noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
}

class _InProcessResponse extends StreamView<List<int>>
    implements HttpClientResponse {
  _InProcessResponse(PostHogResponse response)
      : statusCode = response.status,
        super(Stream.value(utf8.encode(response.body))) {
    response.headers.forEach(headers.set);
  }

  @override
  final int statusCode;

  @override
  final _InProcessHeaders headers = _InProcessHeaders();

  @override
  dynamic noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
}
